#!/usr/bin/env bash
# recipes/crate-windows-aarch64-msvc--0-48-5/build.sh -- stage the windows_aarch64_msvc 0.48.5 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/windows_aarch64_msvc-0.48.5"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"dc35310971f3b2dbbf3f0690a219f40e2d9afcf64f9ab7cc1be722937c26b4bc"}\n' > "${dest}/.cargo-checksum.json"
